content:
:root {
  --color-bg: #f8fafc;
  --color-surface: #ffffff;
  --color-surface-hover: #f1f5f9;
  --color-border: #e2e8f0;
  --color-border-light: #f1f5f9;
  --color-text-main: #0f172a;
  --color-text-muted: #64748b;
  --color-text-light: #94a3b8;

  --color-shibuya: #3b82f6;
  --color-shinjuku: #ec4899;
  --color-umeda: #10b981;

  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05), 0 1px 2px rgba(0, 0, 0, 0.03);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Hiragino Sans', 'Noto Sans JP', sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  padding-bottom: 48px;
}

/* 全体コンテナ */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 20px;
}

/* ヘッダーエリア */
.header-section {
  margin-bottom: 24px;
}

.app-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.app-subtitle {
  font-size: 0.95rem;
  color: var(--color-text-muted);
}

/* メインコンテンツ */
.main-content {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* コントロール・フィルターパネル */
.controls-panel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  padding: 16px 20px;
}

.filter-group {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.filter-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-muted);
  white-space: nowrap;
}

.toggle-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  color: var(--color-text-muted);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
}

.toggle-button:hover {
  background-color: var(--color-surface-hover);
  color: var(--color-text-main);
}

.toggle-button.active {
  background-color: var(--color-surface);
  border-color: var(--color-text-main);
  color: var(--color-text-main);
  box-shadow: var(--shadow-sm);
  font-weight: 600;
}

/* 共通カードサーフェス */
.card-surface {
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

/* 統計サマリーグリッド */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 16px;
}

.stat-card {
  padding: 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.stat-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.stat-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.store-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.95rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  background-color: var(--color-bg);
}

.store-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.stat-label {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin-bottom: 4px;
}

.stat-main-value {
  font-size: 1.875rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--color-text-main);
  margin-bottom: 16px;
}

.stat-sub-items {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  padding-top: 14px;
  border-top: 1px solid var(--color-border-light);
}

.stat-sub-item {
  display: flex;
  flex-direction: column;
}

.stat-sub-label {
  font-size: 0.75rem;
  color: var(--color-text-light);
  margin-bottom: 2px;
}

.stat-sub-value {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-text-main);
}

/* グラフセクション */
.chart-section {
  padding: 24px;
}

.chart-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 20px;
  flex-wrap: wrap;
  gap: 12px;
}

.chart-title-wrapper {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.chart-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.chart-help {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

.chart-wrapper {
  width: 100%;
}

.chart-container {
  width: 100%;
  height: 380px;
}

/* カスタムツールチップ */
.custom-tooltip {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 12px 14px;
  min-width: 160px;
}

.tooltip-title {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--color-text-main);
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--color-border-light);
}

.tooltip-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-size: 0.8125rem;
  padding: 3px 0;
}

.tooltip-color-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--color-text-muted);
}

.tooltip-value {
  font-weight: 700;
  color: var(--color-text-main);
}

/* データテーブルセクション */
.table-section {
  padding: 24px;
}

.table-wrapper {
  width: 100%;
  overflow-x: auto;
  margin-top: 16px;
  -webkit-overflow-scrolling: touch;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
}

.table-header-cell {
  background-color: var(--color-bg);
  color: var(--color-text-muted);
  font-weight: 600;
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-border);
  white-space: nowrap;
}

.table-header-cell:not(:first-child) {
  text-align: right;
}

.table-cell {
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-border-light);
  color: var(--color-text-main);
  white-space: nowrap;
}

.table-cell:not(:first-child) {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.data-table tbody tr:hover {
  background-color: var(--color-surface-hover);
}

/* レスポンシブ対応 */
@media (max-width: 768px) {
  .app-container {
    padding: 16px 12px;
  }

  .app-title {
    font-size: 1.4rem;
  }

  .chart-section,
  .table-section,
  .controls-panel {
    padding: 16px;
  }

  .chart-container {
    height: 300px;
  }

  .stat-card {
    padding: 16px;
  }

  .stat-main-value {
    font-size: 1.5rem;
  }
}

@media (max-width: 480px) {
  .controls-panel {
    flex-direction: column;
    align-items: flex-start;
  }

  .filter-group {
    width: 100%;
  }

  .toggle-button {
    flex: 1;
    justify-content: center;
  }
}

