import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { VisitorChartProps } from '../types';

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    color: string;
    dataKey: string;
  }>;
  label?: string;
}

const CustomTooltip = ({ active, payload, label }: CustomTooltipProps) => {
  if (!active || !payload || payload.length === 0) {
    return null;
  }

  return (
    <div className="custom-tooltip">
      <div className="tooltip-title">{label}</div>
      {payload.map((entry) => (
        <div key={entry.dataKey} className="tooltip-item">
          <div className="tooltip-color-badge">
            <span
              className="store-dot"
              style={{ backgroundColor: entry.color }}
            />
            <span>{entry.name}</span>
          </div>
          <span className="tooltip-value">
            {entry.value.toLocaleString()} 人
          </span>
        </div>
      ))}
    </div>
  );
};

const VisitorChart = ({ data = [], stores = [] }: VisitorChartProps) => {
  const activeStores = stores.filter((store) => store.active);

  return (
    <div className="chart-wrapper">
      <div className="chart-container">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart
            data={data}
            margin={{ top: 10, right: 20, left: 10, bottom: 5 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
            <XAxis
              dataKey="month"
              stroke="#64748b"
              fontSize={12}
              tickLine={false}
              axisLine={{ stroke: '#e2e8f0' }}
            />
            <YAxis
              stroke="#64748b"
              fontSize={12}
              tickLine={false}
              axisLine={{ stroke: '#e2e8f0' }}
              tickFormatter={(value: number) => `${(value / 1000).toFixed(0)}k人`}
              domain={['auto', 'auto']}
            />
            <Tooltip content={<CustomTooltip />} />
            <Legend
              verticalAlign="top"
              align="right"
              wrapperStyle={{ paddingBottom: '16px' }}
              formatter={(value: string) => {
                const store = stores.find((s) => s.key === value);
                return (
                  <span style={{ color: '#0f172a', fontSize: '0.875rem', fontWeight: 500 }}>
                    {store ? store.name : value}
                  </span>
                );
              }}
            />
            {activeStores.map((store) => (
              <Line
                key={store.key}
                type="monotone"
                dataKey={store.key}
                name={store.name}
                stroke={store.color}
                strokeWidth={2.5}
                dot={{ r: 4, strokeWidth: 2, fill: '#ffffff' }}
                activeDot={{ r: 6, stroke: store.color, strokeWidth: 2, fill: store.color }}
              />
            ))}
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default VisitorChart;

import { useState, useMemo } from 'react';
import './index.css';
import { StoreConfig, StoreSummary, StoreKey } from './types';
import { initialStores, monthlyVisitorData } from './data/mockData';
import VisitorChart from './components/VisitorChart';
import StatsCards from './components/StatsCards';

const App = () => {
  const [stores, setStores] = useState<StoreConfig[]>(initialStores);

  const toggleStore = (key: StoreKey) => {
    setStores((prevStores) => {
      const activeCount = prevStores.filter((s) => s.active).length;
      return prevStores.map((store) => {
        if (store.key === key) {
          // 最低1店舗は表示を維持
          if (store.active && activeCount <= 1) {
            return store;
          }
          return { ...store, active: !store.active };
        }
        return store;
      });
    });
  };

  const summaries = useMemo<StoreSummary[]>(() => {
    return stores.map((store) => {
      let total = 0;
      let peakValue = 0;
      let peakMonth = '';

      monthlyVisitorData.forEach((row) => {
        const val = row[store.key];
        total += val;
        if (val > peakValue) {
          peakValue = val;
          peakMonth = row.month;
        }
      });

      const average = Math.round(total / (monthlyVisitorData.length || 1));

      return {
        key: store.key,
        name: store.name,
        color: store.color,
        total,
        average,
        peakMonth,
        peakValue,
      };
    });
  }, [stores]);

  const activeStores = useMemo(
    () => stores.filter((store) => store.active),
    [stores]
  );

  return (
    <div className="app-container">
      <header className="header-section">
        <h1 className="app-title">店舗別来客数ダッシュボード</h1>
        <p className="app-subtitle">
          渋谷店・新宿店・梅田店の月別来客実績の推移と年間統計の比較
        </p>
      </header>

      <main className="main-content">
        {/* コントロール・フィルターパネル */}
        <div className="card-surface controls-panel">
          <div className="filter-group">
            <span className="filter-label">表示店舗フィルター:</span>
            {stores.map((store) => (
              <button
                key={store.key}
                type="button"
                className={`toggle-button ${store.active ? 'active' : ''}`}
                onClick={() => toggleStore(store.key)}
                aria-pressed={store.active}
              >
                <span
                  className="store-dot"
                  style={{
                    backgroundColor: store.active ? store.color : '#cbd5e1',
                  }}
                />
                <span>{store.name}</span>
              </button>
            ))}
          </div>
        </div>

        {/* 統計サマリーカード */}
        <StatsCards summaries={summaries} />

        {/* 折れ線グラフセクション */}
        <section className="card-surface chart-section">
          <div className="chart-header">
            <div className="chart-title-wrapper">
              <h2 className="chart-title">月別来客数トレンド比較</h2>
              <span className="chart-help">
                各データポイントにカーソルを合わせると詳細な来客数が確認できます
              </span>
            </div>
          </div>
          <VisitorChart data={monthlyVisitorData} stores={stores} />
        </section>

        {/* 月別データ詳細テーブル */}
        <section className="card-surface table-section">
          <div className="chart-header">
            <div className="chart-title-wrapper">
              <h2 className="chart-title">月別来客数詳細一覧</h2>
              <span className="chart-help">
                選択されている店舗の来客数実績（単位：人）
              </span>
            </div>
          </div>
          <div className="table-wrapper">
            <table className="data-table">
              <thead>
                <tr>
                  <th className="table-header-cell">月</th>
                  {activeStores.map((store) => (
                    <th key={store.key} className="table-header-cell">
                      <span
                        className="store-dot"
                        style={{
                          backgroundColor: store.color,
                          display: 'inline-block',
                          marginRight: '6px',
                        }}
                      />
                      {store.name}
                    </th>
                  ))}
                  {activeStores.length > 1 && (
                    <th className="table-header-cell">表示店舗 合計</th>
                  )}
                </tr>
              </thead>
              <tbody>
                {monthlyVisitorData.map((row) => {
                  const rowTotal = activeStores.reduce(
                    (acc, store) => acc + row[store.key],
                    0
                  );
                  return (
                    <tr key={row.month}>
                      <td className="table-cell" style={{ fontWeight: 600 }}>
                        {row.month}
                      </td>
                      {activeStores.map((store) => (
                        <td key={store.key} className="table-cell">
                          {row[store.key].toLocaleString()} 人
                        </td>
                      ))}
                      {activeStores.length > 1 && (
                        <td
                          className="table-cell"
                          style={{ fontWeight: 700, color: 'var(--color-text-main)' }}
                        >
                          {rowTotal.toLocaleString()} 人
                        </td>
                      )}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;
